<?php /* In-page screenshot gallery (attendance.js): any [data-shots] element (JSON list of {src,t,a,d,k,m,g}) opens it with previous/next, thumbnails,
   arrow keys and Esc, and a caption with time, screen and activity. The image never navigates away; "Open original" and "Download" are explicit. */ ?>
<dialog class="modal shot-viewer" id="shot-viewer" aria-labelledby="sv-title"><div class="modal-head"><div class="grow"><h3 id="sv-title" data-sv-title>Screenshots</h3><span class="xs muted" data-sv-count></span></div><button type="button" class="btn icon sm ghost" data-close aria-label="Close"><?= icon('x', 'sm') ?></button></div>
  <div class="modal-body"><div class="sv-main"><button type="button" class="btn icon ghost sv-prev" data-sv-step="-1" aria-label="Previous screenshot"><?= icon('chevron-left', 'sm') ?></button><figure class="sv-fig"><img data-sv-img alt=""></figure><button type="button" class="btn icon ghost sv-next" data-sv-step="1" aria-label="Next screenshot"><?= icon('chevron-right', 'sm') ?></button></div>
    <div class="sv-bar"><div class="sv-meta small" data-sv-meta aria-live="polite"></div><div class="sv-acts"><a class="btn sm ghost" data-sv-link target="_blank" rel="noopener"><?= icon('external', 'sm') ?> Open original</a><a class="btn sm ghost" data-sv-dl download><?= icon('download', 'sm') ?> Download</a></div></div>
    <div class="sv-thumbs" data-sv-thumbs></div><p class="xs muted sv-keys mb0">Arrow keys move between screenshots, Esc closes.</p></div></dialog>
